// Read-only character/vehicle catalog compiled into the firmware (flash), so
// the large charactermap.json/tokenmap.json are never parsed on the device.
// The tables live in CatalogData.h, generated by esp32/tools/generate_catalog.py.

#pragma once

#include <cstddef>
#include <cstdint>

namespace ld {

struct CatalogEntry {
  uint16_t id;
  const char *name;
};

// Vehicles and gadgets use ids from 1000, characters below.
constexpr uint16_t FIRST_VEHICLE_ID = 1000;
inline bool isVehicleId(uint16_t id) { return id >= FIRST_VEHICLE_ID; }

// Returns the catalog entry of a character or vehicle id, or nullptr if unknown.
const CatalogEntry *findCharacter(uint16_t id);
const CatalogEntry *findVehicle(uint16_t id);

// Name of any character or vehicle, "N/A" for unknown ids.
const char *catalogName(uint16_t id);

} // namespace ld
